[CANDIDATES_BLOCK]
[
  {
    "label": "기하학적 홈의 발견 (기관 장치 탐색)",
    "narrativeSummary": "손끝에 닿는 거친 암벽의 질감 속에서, 자연적이지 않은 인공적인 미세한 기하학적 선과 홈을 감지합니다. 이 홈이 비고의 문을 여는 개폐 장치인지, 혹은 함정을 작동시키는 시발점인지 분석해야 합니다.",
    "rawMetadata": {
      "foreshadowSeeds": [
        "벽면에 새겨진 화산파의 고대 기문둔갑 흔적"
      ]
    }
  },
  {
    "label": "미세한 바람의 흐름 추적 (출구 탐색)",
    "narrativeSummary": "암벽의 갈라진 틈새 사이로 아주 은밀하게 흘러나오는 차가운 미풍을 느낍니다. 이 미풍이 외부와 연결된 통로의 존재를 증명하는 것인지, 아니면 지하 깊은 곳의 공동으로 이어지는 기류인지 파악하려 시도합니다.",
    "rawMetadata": {
      "foreshadowSeeds": [
        "지하 깊은 곳에서 불어오는 기이한 한기의 기원"
      ]
    }
  },
  {
    "label": "이끼의 비정상적 분포 분석 (진법의 눈 탐색)",
    "narrativeSummary": "축축한 암벽을 덮고 있는 푸른 이끼들 중, 유독 특정 사각형 구역에만 이끼가 자라나지 않은 기묘한 경계를 발견합니다. 고대 진법의 마력이나 기운이 이끼의 생장을 억제하고 있는 것인지 의심해봅니다.",
    "rawMetadata": {
      "foreshadowSeeds": [
        "생명력이 닿지 않는 무형의 진법 영역"
      ]
    }
  }
]
[CANDIDATES_END]

